certs/global.code:
# Caddy gets and renews Let's Encrypt certificates for every site below by
# itself, once each domain's DNS A record points at this server.
# Values come from the caddy service's environment (compose.vps.yml).
{
	email {$ACME_EMAIL}
}

common/common.code:
(common) {
	encode zstd gzip
	# Two blocks on purpose: a deletion (-Server) defers its whole block until the
	# final response, and deferred headers are lost on an error response such as
	# basic_auth's 401. Set right away, these reach the 401 too.
	header {
		Strict-Transport-Security "max-age=31536000"
		X-Content-Type-Options nosniff
		Referrer-Policy strict-origin-when-cross-origin
	}
	# Deferred: also removes the apps' own Server header.
	header -Server
	log {
		output stdout
		format console
	}
}

public/panel.code:
# Control Panel: public, with its own login (hand out the viewer account).
{$PANEL_DOMAIN} {
	import common
	reverse_proxy frontend:80
}

public/code.code:
# Programming lessons: public, static.
{$PROGRAMMING_DOMAIN} {
	import common
	reverse_proxy programming-web:80
}

public/report.code:
# ClinicReport: public demo (synthetic data, one-click demo users, nightly
# reset). Caddy proxies the SignalR WebSocket on /hubs as is.
{$CLINICREPORT_DOMAIN} {
	import common
	reverse_proxy clinicreport:8080
}

lessons/english.code:
# English collocation lessons: public (also on GitHub Pages). Its Context tab
# finds no /api/context here and says it is local-only. /api/sync is the
# review-progress sync (lessons-sync checks its own X-Sync-Key).
{$LESSONS_DOMAIN} {
	import common
	respond /api/context* 404
	handle /api/sync* {
		reverse_proxy lessons-sync:8080
	}
	handle {
		reverse_proxy lessons-web:80
	}
}

lessons/ctx.code:
# The same lessons app as the owner's private Context reader (the phone's
# home-screen app). /api/context is the context engine's export, pushed from
# the PC by push-context.ps1 into CONTEXT_DIR; it is never in the image.
{$CONTEXT_DOMAIN} {
	import common
	import private
	handle /api/context {
		root * /srv/context
		rewrite * /context.json
		header Cache-Control no-store
		file_server
	}
	handle /api/sync* {
		reverse_proxy lessons-sync:8080
	}
	handle {
		reverse_proxy lessons-web:80
	}
}

basicauth/private.code:
# Only the owner's eyes: LedgerDashboard holds the job search (companies,
# contacts), and ctx.<domain> the owner's own reading.
(private) {
	basic_auth {
		{$BASIC_AUTH_USER} {$BASIC_AUTH_HASH}
	}
}

basicauth/ledger.code:
{$LEDGER_DOMAIN} {
	import common
	import private
	reverse_proxy ledgerdashboard:4310
}

clinicsites/hub.code:
# ClinicHub: the sign-in (issuer https://hub.{$CLINIC_DOMAIN}/) and the clinics' own work; pages and API in one container.
hub.{$CLINIC_DOMAIN} {
	import common
	reverse_proxy clinichub:8080
}

clinicsites/app.code:
# The applications whose React app is a separate container: the API's own paths go to the API, the rest to the page.
(app) {
	@api path /api/* /signin-oidc /signout-callback-oidc
	handle @api {
		reverse_proxy {args[0]}
	}
	handle {
		reverse_proxy {args[1]}
	}
}

clinicsites/lab.code:
lab.{$CLINIC_DOMAIN} {
	import common
	import app labflow-api:8080 labflow-web:80
}

layers/redir.code:
# With the clinic platform, LabFlow is the clinic's lab at lab.{$CLINIC_DOMAIN}; its old address sends people there.
# compose.clinic.yml mounts this over deploy/vps/labflow.caddy (same path in the container).
{$LABFLOW_DOMAIN} {
	import common
	redir https://lab.{$CLINIC_DOMAIN}{uri} permanent
}

aliases/aliases.code:
aliases:
  - hub.${CLINIC_DOMAIN}
  - report.${CLINIC_DOMAIN}
  - lab.${CLINIC_DOMAIN}
  - pharmacy.${CLINIC_DOMAIN}
  - finance.${CLINIC_DOMAIN}
  - analytics.${CLINIC_DOMAIN}
  - integration.${CLINIC_DOMAIN}

smoke/smoke.code:
# Public sites; labflow, ledger and ctx sit behind basic auth, so 401 is right.
$expect = [ordered]@{ panel = 200; rebiomed = 200; english = 200; labflow = 401; ledger = 401; ctx = 401 }
$failed = @()
foreach ($site in $expect.Keys) {
    $code = curl.exe -s -o NUL -w '%{http_code}' -m 20 "https://$site.$Domain/"
    $ok = [int]$code -eq $expect[$site]
    Write-Host ("  {0,-9} {1}  {2}" -f $site, $code, $(if ($ok) { 'ok' } else { "expected $($expect[$site])" }))
    if (-not $ok) { $failed += $site }
}
